import attr
import logging
from typing import Optional
from .connection_details import SshServiceDetails, HttpConnectionDetails

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@attr.s(cmp=False)
class NEAT(object):
    """
    This class defines an instance of NEAT.

    :param Optional[SshServiceDetails] ssh_details: SSH details for NEAT node
    :param Optional[HttpConnectionDetails] api_connection_details: HTTP details for NEAT Main URL
    """
    ssh_details = attr.ib(default=None, type=Optional[SshServiceDetails])
    api_connection_details = attr.ib(default=None, type=Optional[HttpConnectionDetails])
